export let lang = 'qq';
export function setLang(l){ if(L[l]) lang=l; try{localStorage.setItem('qq_lang',lang);}catch(e){} document.documentElement.lang = lang==='qq'?'kaa':lang; }
// urgent5: a missing key never prints raw code — fallback current lang -> uz -> en -> qq; a bare key-like token (e.g. "ar_hit") that exists nowhere becomes ''.
// Use has(k) to test whether a key exists (do not compare t(k) with k any more). Placeholders are all replaced; unknown/undefined/NaN values and leftover {x} are removed.
export function has(k){ return !!(k&&((L[lang]&&L[lang][k]!=null)||L.uz[k]!=null||L.en[k]!=null||L.qq[k]!=null)); }
const _warned={};
export function t(k,v){ let s=(L[lang]&&L[lang][k])??L.uz[k]??L.en[k]??L.qq[k];
  if(s==null){ if(typeof k!=='string') return k==null?'':String(k); if(/^[A-Za-z][A-Za-z0-9]*(_[A-Za-z0-9]*)+$/.test(k)){ if(!_warned[k]){ _warned[k]=1; console.warn('[i18n] missing key',k); } return ''; } s=k; }
  s=String(s); if(v) for(const a in v){ const x=v[a]; s=s.split('{'+a+'}').join(x==null||(typeof x==='number'&&!isFinite(x))?'':String(x)); }
  return /\{[a-z][a-z0-9_]*\}/i.test(s)?s.replace(/\{[a-z][a-z0-9_]*\}/gi,'').replace(/\s{2,}/g,' ').trim():s; }
